"% Define the inner and outer loop systems
ki = 12.0;

% Define s variable for transfer function creation
s = tf('s');

% Inner Loop Plant: G_in(s) = 1 / (s * (s + 4.0))
G_in = 1 / (s * (s + 4.0));

% Close the Inner Loop
% Negative feedback with gain ki in the forward path
% G_in_cl(s) = ki * G_in(s) / (1 + ki * G_in(s))
G_in_cl = feedback(ki * G_in, 1);

% Outer Loop Plant: G_out(s) = 2.5 / (s * (s + 2.0))
G_out = 2.5 / (s * (s + 2.0));

% Total Open Loop: L(s) = G_out(s) * G_in_cl(s)
L = G_out * G_in_cl;

% Compute stability margins
% Gm: Gain Margin (linear)
% Pm: Phase Margin (degrees)
% Wcg: Gain Crossover Frequency (rad/s) where magnitude is 1 (0 dB)
% Wcp: Phase Crossover Frequency (rad/s) where phase is -180 degrees
[Gm, Pm, Wcg, Wcp] = margin(L);

% Convert Gain Margin to dB
gm_db = 20 * log10(Gm);

% Create result structure
result = struct();
result.gm_db = gm_db;
result.pm_deg = Pm;
result.w_gc = Wcg;
result.w_pc = Wcp;

% Write results to result.json
fid = fopen('result.json', 'w');
if fid ~= -1
    fprintf(fid, '%s', jsonencode(result));
    fclose(fid);
end"
